//! Hopper SM90 backend (H100/H200).
//!
//! Delegates to TensorRT-LLM via FFI bindings generated by `build.rs`. This
//! file holds the Rust-side glue that adapts the C++ engine to
//! [`ComputeBackend`](crate::traits::ComputeBackend); the kernel calls themselves live in `kernels.rs` once
//! the FFI surface is wired.
//!
//! Stubbed at the trait level for now: methods return `anyhow!` "not wired"
//! so a `--features sm90` build links and typechecks but is not runnable until
//! `build.rs` produces the bindings and `kernels.rs` calls them.
//!
//! Submodules:
//! - [`backend`] — `HopperBackend` struct + its `ComputeBackend` impl.

mod backend;
mod forward;
mod decode_profile;
mod forward_device;
mod ops;

pub use backend::HopperBackend;
pub use forward::{KvCache, Qwen2Dims};
pub use decode_profile::DecodeProfile;
pub use forward_device::DecodeMode;
